import{_ as i,o as a,c as e,ao as n}from"./chunks/framework.DM2KPRmX.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ReactiveKernels.jl","text":"have → want kernel planning","tagline":"Lower a dataflow graph and a have/want query into a specialized, straight-line Julia kernel — no traversal, no scheduling, no interpretation on the hot path.","actions":[{"theme":"brand","text":"API Reference","link":"/api"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/nsiccha/ReactiveKernels.jl"}]},"features":[{"title":"Plan once, run millions of times","details":"Preparation keeps exactly the steps needed to turn what you have into what you want, picks between alternative ways to compute a value, and reuses shared subexpressions — then generates an ordinary Julia function."},{"title":"A prepared kernel is just straight-line code","details":"While it runs there is no graph to walk, nothing to schedule, and no cache to look up. All of that bookkeeping happens once, during preparation, not on every call."},{"title":"Optional buffer-reusing execution","details":"prepare_nonallocating rewrites the generated function to reuse the same arrays across calls, so how much it allocates is separate from what the graph computes."},{"title":"Deliberately narrow","details":"No scheduler inside a prepared kernel, no probabilistic-programming semantics, and no symbolic algebra. It turns pure dataflow graphs into fast plain-Julia functions and refuses code whose side effects it cannot check."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),t={name:"index.md"};function l(h,s,p,k,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n("",36)])])}const g=i(t,[["render",l]]);export{c as __pageData,g as default};
